// specs/login-and-tenant-selection.spec.ts
// Spec file — Login and Tenant Selection
// Source: ui/input.txt (raw-file)
// Generated by: ui-testcase-orchestrator (dry-run)
import { test, expect } from '@playwright/test';
import { LoginPage } from '../pages/login.page';
import { MultiTenantDashboardPage } from '../pages/multi-tenant-dashboard.page';
import { config } from '../config/test-config';

test.describe('Login and Tenant Selection', () => {
  let loginPage: LoginPage;
  let dashboardPage: MultiTenantDashboardPage;
  let navItems: string[] = [];
  let selectedTenantName = '';

  test.beforeEach(async ({ page }) => {
    loginPage = new LoginPage(page);
    dashboardPage = new MultiTenantDashboardPage(page);
    await loginPage.goto();
  });

  // Source file: input.txt | Scenario: Login and select the first visible tenant from the list
  test('Login with admin credentials and select the first visible tenant from the list', async ({ page }) => {

    await test.step('Login into https://trilogy-go-qa01.purplecheckpoint.com/', async () => {
      console.log('▶ Login into https://trilogy-go-qa01.purplecheckpoint.com/');
      await loginPage.assertIsLoginPage();
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-login-page.png' });
    });

    await test.step('Enter the username as admin', async () => {
      console.log('▶ Enter the username as admin');
      await loginPage.fillUsername(config.username);
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-enter-username.png' });
    });

    await test.step('Enter the password as Tr1l0gy@123', async () => {
      console.log('▶ Enter the password as Tr1l0gy@123');
      await loginPage.fillPassword(config.password);
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-enter-password.png' });
    });

    await test.step('Click on Sign In button', async () => {
      console.log('▶ Click on Sign In button');
      await loginPage.clickSignIn();
      // Wait for either the multi-tenant dashboard or a redirect
      await page.waitForURL(/\/#\/multi-tenant/, { timeout: 15000 });
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-after-sign-in.png' });
    });
    await test.step('Check Multi-Tenant Selection popup appears', async () => {
      console.log('▶ Check Multi-Tenant Selection popup appears');
      await dashboardPage.assertMultiTenantDialogVisible();
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-multi-tenant-dialog.png' });
    });

    await test.step('Click on the choose your tenant dropdown', async () => {
      console.log('▶ Click on the choose your tenant dropdown');
      await dashboardPage.clickChooseTenantDropdown();
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-dropdown-open.png' });
    });

    await test.step('Select the first visible tenant from the dropdown list', async () => {
      console.log('▶ Select the first visible tenant from the dropdown list');
      await dashboardPage.selectFirstTenantOption();
      await dashboardPage.assertIsDashboard();
      selectedTenantName = await dashboardPage.getSelectedTenantName();
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-tenant-selected.png' });
    });

    await test.step('Get all the pages that are under the hamburger menu', async () => {
      console.log('▶ Get all the pages that are under the hamburger menu');
      navItems = await dashboardPage.getNavMenuItems();
      expect(navItems.length).toBeGreaterThan(0);
      await page.screenshot({ path: 'test-results/screenshots/login-and-tenant-selection-nav-items.png' });
    });

    await test.step('Navigate to each of the pages and validate if all the pages is displaying the tenant that we selected initially', async () => {
      console.log('▶ Navigate to each of the pages and validate tenant is displayed on each page');
      for (const navItem of navItems) {
        await dashboardPage.clickNavItem(navItem);
        await dashboardPage.assertTenantInHeader(selectedTenantName);
        await page.screenshot({ path: `test-results/screenshots/login-and-tenant-selection-page-${navItem.toLowerCase().replace(/\s+/g, '-')}.png` });
      }
    });

  });

});
